@font-face{font-family:"Pretendard";font-style:normal;font-weight:600;font-display:swap;src:url("https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/static/woff2/Pretendard-SemiBold.woff2") format("woff2")}
@font-face{font-family:"Pretendard";font-style:normal;font-weight:900;font-display:swap;src:url("https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/static/woff2/Pretendard-Black.woff2") format("woff2")}

:root{
  --navy-900:#203864; --navy-700:#2774B8; --navy-400:#5B9BD5;
  --navy-200:#B4C3D6; --navy-050:#D9EEFC;
  --ink-1000:#000000; --ink-900:#111111; --ink-600:#404040; --ink-300:#A5A5A5;
  --paper-200:#E7E6E6; --paper-000:#FFFFFF;
  --dia-blue-fill:#D9EEFC;   --dia-blue-line:#2774B8;
  --dia-green-fill:#E4F4E4;  --dia-green-line:#3D8C54;
  --dia-orange-fill:#FFEBC9; --dia-orange-line:#E97820;
  --dia-purple-fill:#EADCF5; --dia-purple-line:#6D237C;
  --emphasis-red:#FF0000;
  --font-display:"Pretendard","Noto Sans KR","Malgun Gothic",sans-serif;
  --font-core:Arial,"Arimo","Malgun Gothic",Helvetica,sans-serif;
  --font-hangul:"Noto Sans KR","Malgun Gothic",sans-serif;
  --font-mono:Consolas,"Courier New",monospace;
  --type-slide-title:37.33px; --type-lead:26.67px;
  --type-body-1:32px; --type-body-2:26.67px; --type-body-3:24px;
  --type-diagram-ko:26.67px; --type-diagram-en:21.33px;
  --type-footer:16px; --type-slide-number:24px;
  --radius-block:14px; --stroke-diagram:4px; --stroke-arrow:8px;
}

/* ========================================================== viewer chrome */
html,body{margin:0;height:100%;background:var(--paper-200);font-family:var(--font-core)}
#viewport{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;overflow:hidden}
#deck{width:1280px;height:720px;transform-origin:center center;position:relative}
.slide{position:absolute;inset:0;width:1280px;height:720px;background:var(--paper-000);overflow:hidden;display:none}
.slide.is-active{display:block}
#hud{position:fixed;right:10px;top:6px;z-index:40;font:400 13px var(--font-core);color:var(--ink-600);
     background:rgba(255,255,255,.9);padding:3px 8px;border:1px solid var(--navy-200)}
#hud b{color:var(--navy-900)}
#help{position:fixed;left:10px;top:6px;z-index:40;font:400 12.5px var(--font-core);color:var(--ink-600);
      background:rgba(255,255,255,.9);padding:3px 8px;border:1px solid var(--navy-200);transition:opacity .4s}
#help.faded{opacity:0;pointer-events:none}

body.overview #viewport{align-items:flex-start;justify-content:flex-start;overflow:auto;padding:18px}
body.overview #deck{width:auto;height:auto;transform:none!important;display:grid;
     grid-template-columns:repeat(auto-fill,320px);gap:14px}
body.overview .slide{position:relative;display:block;inset:auto;
     transform:scale(.25);transform-origin:top left;width:1280px;height:720px;
     margin:0 -960px -540px 0;outline:1px solid var(--navy-200);cursor:pointer}
body.overview .slide.is-active{outline:3px solid var(--navy-900)}

/* ==================================================== content-slide chrome */
.bar{position:absolute;left:20.9px;top:13.5px;width:9.8px;height:63.4px;background:var(--navy-900)}
.slide > h2{position:absolute;left:46px;top:13.5px;right:88px;height:63.4px;margin:0;display:flex;
     align-items:center;font:700 var(--type-slide-title)/.9 var(--font-core);
     color:var(--navy-900);letter-spacing:-.01em}
.mark{position:absolute;left:1198.7px;top:14.4px;width:62px;height:62px;opacity:.5;
     filter:grayscale(1) brightness(1.1) sepia(1) hue-rotate(178deg) saturate(3.2)}
.foot{position:absolute;left:0;right:0;top:694.2px;height:26.5px;background:var(--navy-900)}
.foot-num-band{position:absolute;right:0;top:694.2px;width:331.6px;height:26.5px;background:var(--navy-200)}
.foot-credit{position:absolute;left:8px;top:694.2px;height:26.5px;display:flex;align-items:center;
     font:italic 700 var(--type-footer)/1 var(--font-core);color:#fff}
.foot-num{position:absolute;left:1215.9px;width:63.2px;top:694.2px;height:26.5px;display:flex;
     align-items:center;justify-content:center;
     font:700 var(--type-slide-number)/1 var(--font-core);color:var(--ink-600)}

.lead{position:absolute;left:48.4px;top:98px;right:40px;margin:0;
     font:700 var(--type-lead)/1.15 var(--font-core);color:var(--ink-1000)}
.content{position:absolute;left:23px;right:23px;top:150px;bottom:30px}
.content.nolead{top:92px}

/* ======================================================== body type */
.body{font:400 var(--type-body-3)/1.34 var(--font-core);color:var(--ink-1000)}
ul.lec{list-style:none;margin:0;padding:0}
ul.lec > li{position:relative;padding-left:24px;margin-bottom:14px;
     font:400 var(--type-body-2)/1.25 var(--font-core);color:var(--ink-1000)}
ul.lec > li::before{content:"\2022";position:absolute;left:2px;color:var(--ink-1000)}
ul.lec ul{list-style:none;margin:6px 0 0;padding:0}
ul.lec ul > li{position:relative;padding-left:28px;margin-bottom:5px;
     font:400 var(--type-body-3)/1.25 var(--font-core)}
ul.lec ul > li::before{content:"\2192";position:absolute;left:2px;font-family:var(--font-core)}
p.def{margin:0 0 14px;font:400 var(--type-body-3)/1.34 var(--font-core);color:var(--ink-1000)}
p.def > b{font-style:italic;font-weight:700}
.red{color:var(--emphasis-red)}
.dim{color:var(--ink-600)}
.cap{margin:8px 0 0;font:400 19px/1.25 var(--font-core);color:var(--ink-600)}
.sub-h{margin:0 0 8px;font:700 22px/1.2 var(--font-core);color:var(--navy-900)}

/* equations (KaTeX) — navy keyline on the left marks the key result */
.katex{font-size:1.1em;color:inherit}
.eq{margin:0 0 8px;font:400 29px/1.45 var(--font-core);color:var(--ink-1000)}
.eq.sm{font-size:25px}
.eq .katex-display{margin:.2em 0;text-align:left}
.eq .katex-display > .katex{text-align:left}
.eqbox{border-left:var(--stroke-diagram) solid var(--navy-900);padding:6px 0 6px 20px;margin:0 0 16px}
.eqbox .eq:last-child{margin-bottom:0}
.eqlabel{display:inline-block;min-width:190px;font:700 21px/1 var(--font-core);color:var(--navy-900)}

/* tables — hairline only, no fills */
table.t{border-collapse:collapse;width:100%;font:400 21px/1.28 var(--font-core);color:var(--ink-1000)}
table.t th{text-align:left;font-weight:700;color:var(--navy-900);padding:7px 14px 7px 0;
     border-bottom:2px solid var(--navy-900);vertical-align:bottom}
table.t td{padding:8px 14px 8px 0;border-bottom:1px solid var(--paper-200);vertical-align:middle}
table.t.sm{font-size:19.5px}
table.t tr:last-child td{border-bottom:none}

/* layout helpers */
.two{display:flex;gap:34px;align-items:flex-start}
.two > *{flex:1;min-width:0}
.fig{position:relative}
.fig svg{display:block}
.flab{position:absolute;font:400 22px/1 var(--font-core);color:var(--ink-900);white-space:nowrap}

/* diagram blocks */
.row{display:flex;align-items:center;justify-content:center}
.blk{box-sizing:border-box;border-radius:var(--radius-block);border:var(--stroke-diagram) solid;
     display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;
     padding:0 12px;text-align:center}
.blk .nm{font:700 var(--type-diagram-ko)/1.05 var(--font-core);color:var(--ink-900)}
.blk .en{font:400 var(--type-diagram-en)/1.15 var(--font-core);color:var(--ink-900)}
.blk .sub{font:400 19px/1.2 var(--font-core);color:var(--ink-600)}
.t-blue{background:var(--dia-blue-fill);border-color:var(--dia-blue-line)}
.t-green{background:var(--dia-green-fill);border-color:var(--dia-green-line)}
.t-orange{background:var(--dia-orange-fill);border-color:var(--dia-orange-line)}
.t-purple{background:var(--dia-purple-fill);border-color:var(--dia-purple-line)}
.abs{position:absolute}
.arw{height:var(--stroke-arrow);background:var(--ink-900);position:relative;flex:0 0 auto}
.arw::after{content:"";position:absolute;right:-16px;top:-9px;
     border-left:17px solid var(--ink-900);border-top:13px solid transparent;border-bottom:13px solid transparent}
.vline{width:var(--stroke-arrow);background:var(--ink-900);position:absolute}
.hline{height:var(--stroke-arrow);background:var(--ink-900);position:absolute}
.tri-d{position:absolute;width:0;height:0;border-top:17px solid var(--ink-900);
     border-left:13px solid transparent;border-right:13px solid transparent}
.op-oval{box-sizing:border-box;width:58px;height:58px;border:2px solid var(--ink-900);border-radius:50%;
     display:flex;align-items:center;justify-content:center;font:400 34px/1 var(--font-core);color:var(--ink-900);
     flex:0 0 auto}
.op-txt{font:400 40px/1 var(--font-core);color:var(--ink-900);padding:0 16px}

/* equation grid (slide: ten equations) */
.eqgrid{display:grid;grid-template-columns:.9fr 1.1fr;column-gap:40px;row-gap:0}
.eqgrid > div{display:flex;align-items:center;gap:14px;padding:9px 0;border-bottom:1px solid var(--paper-200)}
.eqgrid .n{flex:0 0 34px;font:700 22px/1 var(--font-core);color:var(--navy-900)}
.eqgrid .k{flex:0 0 180px;font:400 19px/1.2 var(--font-core);color:var(--ink-600)}
.eqgrid .m{font-size:22px;white-space:nowrap}

/* textbook figures — placed at natural aspect, source named underneath */
.tfig{display:flex;flex-direction:column;align-items:center}
.tfig img{display:block;object-fit:contain}
.tfig .src{margin-top:6px;font:400 16px/1.2 var(--font-core);color:var(--ink-600);text-align:center}

p.code{margin:0 0 6px;font:400 19px/1.3 var(--font-mono);color:var(--navy-900);border-left:var(--stroke-diagram) solid var(--navy-200);padding:2px 0 2px 12px}
.codebox{border-left:var(--stroke-diagram) solid var(--navy-200);padding:0 0 4px 14px;min-width:0}
.codebox p.code{border:none;padding:0;margin:0;white-space:pre;font-size:15.5px;line-height:1.36;color:var(--ink-900)}
.codebox p.code-file{margin:0 0 8px;font:700 16px/1.2 var(--font-core);color:var(--navy-700)}
.code .cm{color:var(--dia-green-line)}

/* ======================================================================= cover */
.slide.cover{background:var(--navy-900)}
.cover .rule{position:absolute;left:35.5px;width:1209px;height:8.25px;background:rgba(255,255,255,.6)}
.cover .rule.top{top:59.1px}
.cover .rule.bot{top:663.7px}
.cover .mark-lg{position:absolute;left:1075.8px;top:460.9px;width:138px;height:137.6px;opacity:.5;
     filter:grayscale(1) brightness(2.4) contrast(1.6)}
.cover .title-box{position:absolute;left:36px;top:117.8px;width:1209px;height:228.8px;
     display:flex;flex-direction:column;justify-content:flex-end;align-items:center}
.cover h1{margin:0;text-align:center;font:900 52px/1.02 var(--font-display);color:#fff}
.cover .meta{position:absolute;left:35.5px;top:419px;width:960px;display:flex;flex-direction:column;
     gap:2px;font:600 32px/1.1 var(--font-display);color:#fff}
.cover .sub{position:absolute;left:35.5px;top:600px;width:1000px;
     font:400 21px/1.35 var(--font-core);color:rgba(255,255,255,.75)}

/* ======================================================================= print */
@page{size:1280px 720px;margin:0}
@media print{
  html,body{background:#fff;height:auto}
  #viewport{position:static;display:block;overflow:visible}
  #deck{transform:none!important;width:1280px;height:auto}
  .slide{position:relative;display:block!important;inset:auto;page-break-after:always;break-after:page}
  #hud,#help{display:none}
}
</style>
</head>
